export class ResultsComponent {
  // =========================================================
  // Constructor
  // =========================================================
  constructor(resultService) {
    this.resultService = resultService;
    // =========================================================
    // Results Data
    // =========================================================
    this.results = [];
    // =========================================================
    // Filters
    // =========================================================
    this.searchText = '';
    this.selectedStatus = 'All Status';
    // =========================================================
    // Loading / Error
    // =========================================================
    this.loading = false;
    this.errorMessage = '';
    // =========================================================
    // Modals
    // =========================================================
    this.showAddModal = false;
    this.showViewModal = false;
    this.showEditModal = false;
    // =========================================================
    // Selected Result
    // =========================================================
    this.selectedResult = null;
    // =========================================================
    // New Result
    // =========================================================
    this.newResult = {
      student: '',
      exam: '',
      marks: 0,
      totalMarks: 100
    };
    // =========================================================
    // Edit Result
    // =========================================================
    this.editMarks = 0;
  }
  // =========================================================
  // Lifecycle
  // =========================================================
  ngOnInit() {
    this.loadResults();
  }
  // =========================================================
  // Load Results
  // =========================================================
  loadResults() {
    this.loading = true;
    this.errorMessage = '';
    this.resultService.getAllResults().subscribe({
      next: response => {
        this.results = response?.data || [];
        this.loading = false;
      },
      error: error => {
        console.error('Error loading results:', error);
        this.errorMessage = error?.error?.message || 'Failed to load results';
        this.loading = false;
      }
    });
  }
  // =========================================================
  // Filtered Results
  // =========================================================
  get filteredResults() {
    const search = this.searchText.toLowerCase().trim();
    return this.results.filter(result => {
      const studentName = this.getStudentName(result).toLowerCase();
      const studentCode = this.getStudentCode(result).toLowerCase();
      const examTitle = this.getExamTitle(result).toLowerCase();
      const matchesSearch = !search || studentName.includes(search) || studentCode.includes(search) || examTitle.includes(search);
      const matchesStatus = this.selectedStatus === 'All Status' || this.selectedStatus === 'Passed' && result.isPassed === true || this.selectedStatus === 'Failed' && result.isPassed === false;
      return matchesSearch && matchesStatus;
    });
  }
  // =========================================================
  // Statistics
  // =========================================================
  get totalResults() {
    return this.results.length;
  }
  get passedResults() {
    return this.results.filter(result => result.isPassed === true).length;
  }
  get failedResults() {
    return this.results.filter(result => result.isPassed === false).length;
  }
  get averagePercentage() {
    if (!this.results.length) {
      return 0;
    }
    const totalPercentage = this.results.reduce((sum, result) => {
      return sum + this.getPercentage(result);
    }, 0);
    return totalPercentage / this.results.length;
  }
  // =========================================================
  // Student Helpers
  // =========================================================
  getStudentName(result) {
    return result?.student?.userId?.name || 'Unknown';
  }
  getStudentCode(result) {
    return result?.student?.studentCode || '-';
  }
  getInitials(name) {
    return name.split(' ').filter(word => word.length > 0).map(word => word.charAt(0)).join('').substring(0, 2).toUpperCase();
  }
  // =========================================================
  // Exam Helpers
  // =========================================================
  getExamTitle(result) {
    return result?.exam?.title || 'Unknown Exam';
  }
  // =========================================================
  // Marks
  // =========================================================
  getMarks(result) {
    return Number(result?.marks || 0);
  }
  getTotalMarks(result) {
    return Number(result?.exam?.totalMarks || result?.totalMarks || 0);
  }
  // =========================================================
  // Percentage
  // =========================================================
  getPercentage(result) {
    const marks = this.getMarks(result);
    const total = this.getTotalMarks(result);
    if (!total) {
      return 0;
    }
    return marks / total * 100;
  }
  // =========================================================
  // Add Result
  // =========================================================
  openAddResult() {
    this.newResult = {
      student: '',
      exam: '',
      marks: 0,
      totalMarks: 100
    };
    this.showAddModal = true;
  }
  // =========================================================
  // Close Add Result Modal
  // =========================================================
  closeAddResult() {
    this.showAddModal = false;
  }
  // =========================================================
  // Save Result
  // =========================================================
  saveResult() {
    if (!this.newResult.student.trim() || !this.newResult.exam.trim()) {
      return;
    }
    /*
      Currently this keeps the same behavior
      as your original Results module.
           When createResult() is available inside
      ResultService, connect the API here.
    */
    console.log('New result:', this.newResult);
    this.closeAddResult();
  }
  // =========================================================
  // View Result
  // =========================================================
