import { Component, OnInit } from '@angular/core';
import { ResultService } from '../../../services/results/results.service';

@Component({
  selector: 'app-results',
  templateUrl: './results.component.html',
  styleUrls: ['./results.component.css']
})
export class ResultsComponent implements OnInit {

  // =========================================================
  // Results Data
  // =========================================================

  results: any[] = [];

  // =========================================================
  // Filters
  // =========================================================

  searchText: string = '';
  selectedStatus: string = 'All Status';

  // =========================================================
  // Loading / Error
  // =========================================================

  loading: boolean = false;
  errorMessage: string = '';

  // =========================================================
  // Modals
  // =========================================================

  showAddModal: boolean = false;
  showViewModal: boolean = false;
  showEditModal: boolean = false;

  // =========================================================
  // Selected Result
  // =========================================================

  selectedResult: any = null;

  // =========================================================
  // New Result
  // =========================================================

  newResult = {
    student: '',
    exam: '',
    marks: 0,
    totalMarks: 100
  };

  // =========================================================
  // Edit Result
  // =========================================================

  editMarks: number = 0;

  // =========================================================
  // Constructor
  // =========================================================

  constructor(
    private resultService: ResultService
  ) {}

  // =========================================================
  // Lifecycle
  // =========================================================

  ngOnInit(): void {
    this.loadResults();
  }

  // =========================================================
  // Load Results
  // =========================================================

  loadResults(): void {

    this.loading = true;
    this.errorMessage = '';

    this.resultService
      .getAllResults()
      .subscribe({

        next: (response: any) => {

          this.results = response?.data || [];

          this.loading = false;
        },

        error: (error: any) => {

          console.error(
            'Error loading results:',
            error
          );

          this.errorMessage =
            error?.error?.message ||
            'Failed to load results';

          this.loading = false;
        }

      });
  }

  // =========================================================
  // Filtered Results
  // =========================================================

  get filteredResults(): any[] {

    const search =
      this.searchText
        .toLowerCase()
        .trim();

    return this.results.filter(
      (result: any) => {

        const studentName =
          this.getStudentName(result)
            .toLowerCase();

        const studentCode =
          this.getStudentCode(result)
            .toLowerCase();

        const examTitle =
          this.getExamTitle(result)
            .toLowerCase();

        const matchesSearch =
          !search ||
          studentName.includes(search) ||
          studentCode.includes(search) ||
          examTitle.includes(search);

        const matchesStatus =
          this.selectedStatus === 'All Status' ||
          (
            this.selectedStatus === 'Passed' &&
            result.isPassed === true
          ) ||
          (
            this.selectedStatus === 'Failed' &&
            result.isPassed === false
          );

        return (
          matchesSearch &&
          matchesStatus
        );
      }
    );
  }

  // =========================================================
  // Statistics
  // =========================================================

  get totalResults(): number {
    return this.results.length;
  }

  get passedResults(): number {

    return this.results.filter(
      (result: any) =>
        result.isPassed === true
    ).length;
  }

  get failedResults(): number {

    return this.results.filter(
      (result: any) =>
        result.isPassed === false
    ).length;
  }

  get averagePercentage(): number {

    if (!this.results.length) {
      return 0;
    }

    const totalPercentage =
      this.results.reduce(
        (
          sum: number,
          result: any
        ) => {

          return (
            sum +
            this.getPercentage(result)
          );

        },
        0
      );

    return (
      totalPercentage /
      this.results.length
    );
  }

  // =========================================================
  // Student Helpers
  // =========================================================

  getStudentName(result: any): string {

    return (
      result?.student?.userId?.name ||
      'Unknown'
    );
  }

  getStudentCode(result: any): string {

    return (
      result?.student?.studentCode ||
      '-'
    );
  }

  getInitials(name: string): string {

    return name
      .split(' ')
      .filter(word => word.length > 0)
      .map(word => word.charAt(0))
      .join('')
      .substring(0, 2)
      .toUpperCase();
  }

  // =========================================================
  // Exam Helpers
  // =========================================================

  getExamTitle(result: any): string {

    return (
      result?.exam?.title ||
      'Unknown Exam'
    );
  }

  // =========================================================
  // Marks
  // =========================================================

  getMarks(result: any): number {

    return Number(
      result?.marks || 0
    );
  }

  getTotalMarks(result: any): number {

    return Number(
      result?.exam?.totalMarks ||
      result?.totalMarks ||
      0
    );
  }

  // =========================================================
  // Percentage
  // =========================================================

  getPercentage(result: any): number {

    const marks =
      this.getMarks(result);

    const total =
      this.getTotalMarks(result);

    if (!total) {
      return 0;
    }

    return (
      (marks / total) * 100
    );
  }

  // =========================================================
  // Add Result
  // =========================================================

  openAddResult(): void {

    this.newResult = {
      student: '',
      exam: '',
      marks: 0,
      totalMarks: 100
    };

    this.showAddModal = true;
  }

  // =========================================================
  // Close Add Result Modal
  // =========================================================

  closeAddResult(): void {

    this.showAddModal = false;
  }

  // =========================================================
  // Save Result
  // =========================================================

  saveResult(): void {

    if (
      !this.newResult.student.trim() ||
      !this.newResult.exam.trim()
    ) {
      return;
    }

    /*
      Currently this keeps the same behavior
      as your original Results module.

      When createResult() is available inside
      ResultService, connect the API here.
    */

    console.log(
      'New result:',
      this.newResult
    );

    this.closeAddResult();
  }

  // =========================================================
  // View Result
  // =========================================================

  viewResult(result: any): void {

    this.selectedResult = result;

    this.showViewModal = true;
  }

  // =========================================================
  // Close Details Modal
  // =========================================================

  closeViewResult(): void {

    this.showViewModal = false;

    this.selectedResult = null;
  }

  // =========================================================
  // Edit Result
  // =========================================================

  editResult(result: any): void {

    this.selectedResult = result;

    this.editMarks =
      this.getMarks(result);

    this.showEditModal = true;
  }

  // =========================================================
  // Close Edit Modal
  // =========================================================

  closeEditResult(): void {

    this.showEditModal = false;

    this.selectedResult = null;

    this.editMarks = 0;
  }

  // =========================================================
  // Update Result
  // =========================================================

  updateResult(): void {

    if (!this.selectedResult) {
      return;
    }

    this.selectedResult.marks =
      Number(this.editMarks);

    const total =
      this.getTotalMarks(
        this.selectedResult
      );

    if (total > 0) {

      const percentage =
        (
          Number(this.editMarks) /
          total
        ) * 100;

      this.selectedResult.isPassed =
        percentage >= 50;
    }

    this.closeEditResult();
  }

  // =========================================================
  // Delete Result
  // =========================================================

  deleteResult(result: any): void {

    const id =
      result?._id;

    if (!id) {

      console.error(
        'Result ID not found.'
      );

      return;
    }

    const confirmed =
      confirm(
        `Are you sure you want to delete the result of ${this.getStudentName(result)}?`
      );

    if (!confirmed) {
      return;
    }

    this.resultService
      .deleteResult(id)
      .subscribe({

        next: () => {

          this.results =
            this.results.filter(
              (item: any) =>
                item._id !== id
            );
        },

        error: (error: any) => {

          console.error(
            'Error deleting result:',
            error
          );

          alert(
            error?.error?.message ||
            'Failed to delete result'
          );
        }

      });
  }

}
<section class="results-page">

  <!-- =========================================================
       Header
  ========================================================= -->

  <div class="results-header-banner">

    <div class="results-page__header">

      <div>
        <h2 class="results-page__title">
          Results
        </h2>

        <p class="results-page__subtitle">
          Manage and review student examination results.
        </p>
      </div>

      <div class="results-page__actions">

        <button
          type="button"
          class="btn btn--primary"
          (click)="openAddResult()"
        >
          <i class="fa-solid fa-plus"></i>

          Add Result
        </button>

      </div>

    </div>

  </div>


  <!-- =========================================================
       Statistics
  ========================================================= -->

  <div class="stats-grid">

    <!-- Total Results -->

    <div class="stat-card">

      <div class="stat-icon stat-icon--blue">
        <i class="fa-solid fa-chart-column"></i>
      </div>

      <div class="stat-content">

        <span class="stat-title">
          Total Results
        </span>

        <strong>
          {{ totalResults }}
        </strong>

        <span class="stat-description">
          All student results
        </span>

      </div>

    </div>


    <!-- Passed -->

    <div class="stat-card">

      <div class="stat-icon stat-icon--green">
        <i class="fa-solid fa-circle-check"></i>
      </div>

      <div class="stat-content">

        <span class="stat-title">
          Passed
        </span>

        <strong>
          {{ passedResults }}
        </strong>

        <span class="stat-description">
          Successful results
        </span>

      </div>

    </div>


    <!-- Failed -->

    <div class="stat-card">

      <div class="stat-icon stat-icon--orange">
        <i class="fa-solid fa-circle-exclamation"></i>
      </div>

      <div class="stat-content">

        <span class="stat-title">
          Failed
        </span>

        <strong>
          {{ failedResults }}
        </strong>

        <span class="stat-description">
          Unsuccessful results
        </span>

      </div>

    </div>


    <!-- Average -->

    <div class="stat-card">

      <div class="stat-icon stat-icon--purple">
        <i class="fa-solid fa-percent"></i>
      </div>

      <div class="stat-content">

        <span class="stat-title">
          Average Marks
        </span>

        <strong>
          {{ averagePercentage | number:'1.0-1' }}%
        </strong>

        <span class="stat-description">
          Average student percentage
        </span>

      </div>

    </div>

  </div>


  <!-- =========================================================
       Results List
  ========================================================= -->

  <div class="results-card">

    <!-- Card Header -->

    <div class="results-card__header">

      <div>

        <h3>
          Student Results
        </h3>

        <p>
          {{ filteredResults.length }} results found
        </p>

      </div>


      <!-- Filters -->

      <div class="results-filters">

        <!-- Status Filter -->

        <select
          [(ngModel)]="selectedStatus"
        >

          <option value="All Status">
            All Status
          </option>

          <option value="Passed">
            Passed
          </option>

          <option value="Failed">
            Failed
          </option>

        </select>


        <!-- Search -->

        <div class="search-box">

          <svg
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
          >

            <circle
              cx="11"
              cy="11"
              r="8"
            ></circle>

            <path
              d="m21 21-4.3-4.3"
            ></path>

          </svg>

          <input
            type="text"
            [(ngModel)]="searchText"
            placeholder="Search results..."
          />

        </div>

      </div>

    </div>


    <!-- =======================================================
         Loading
    ======================================================== -->

    <div
      class="state-message"
      *ngIf="loading"
    >

      <i class="fa-solid fa-spinner fa-spin"></i>

      Loading results...

    </div>


    <!-- =======================================================
         Error
    ======================================================== -->

    <div
      class="state-message state-message--error"
      *ngIf="!loading && errorMessage"
    >

      <i class="fa-solid fa-circle-exclamation"></i>

      {{ errorMessage }}

    </div>


    <!-- =======================================================
         Results Table
    ======================================================== -->

    <div
      class="table-wrapper"
      *ngIf="!loading && !errorMessage"
    >

      <table class="results-table">

        <thead>

          <tr>

            <th>
              STUDENT
            </th>

            <th>
              STUDENT CODE
            </th>

            <th>
              EXAM
            </th>

            <th>
              MARKS
            </th>

            <th>
              PERCENTAGE
            </th>

            <th>
              STATUS
            </th>

            <th>
              ACTIONS
            </th>

          </tr>

        </thead>


        <tbody>

          <!-- =================================================
               Result Rows
          ================================================== -->

          <tr
            *ngFor="let result of filteredResults"
          >

            <!-- Student -->

            <td>

              <div class="student-cell">

                <div class="student-avatar">
                  {{ getInitials(getStudentName(result)) }}
                </div>

                <div class="student-info">

                  <strong>
                    {{ getStudentName(result) }}
                  </strong>

                  <span>
                    Student
                  </span>

                </div>

              </div>

            </td>


            <!-- Student Code -->

            <td>

              <span class="code-badge">
                {{ getStudentCode(result) }}
              </span>

            </td>


            <!-- Exam -->

            <td>

              <div class="exam-cell">

                <div class="exam-avatar">

                  <i class="fa-solid fa-file-lines"></i>

                </div>

                <div class="exam-info">

                  <strong>
                    {{ getExamTitle(result) }}
                  </strong>

                  <span>
                    Examination
                  </span>

                </div>

              </div>

            </td>


            <!-- Marks -->

            <td>

              <span class="marks">

                <strong>
                  {{ getMarks(result) }}
                </strong>

                /
                {{ getTotalMarks(result) }}

              </span>

            </td>


            <!-- Percentage -->

            <td>

              <span class="percentage">

                {{ getPercentage(result) | number:'1.0-1' }}%

              </span>

            </td>


            <!-- Status -->

            <td>

              <span
                class="status-badge"
                [class.status-badge--active]="result.isPassed === true"
                [class.status-badge--inactive]="result.isPassed === false"
              >

                <span></span>

                {{ result.isPassed ? 'Passed' : 'Failed' }}

              </span>

            </td>


            <!-- Actions -->

            <td>

              <div class="actions">

                <!-- View -->

                <button
                  type="button"
                  title="View"
                  (click)="viewResult(result)"
                >

                  <i class="fa-regular fa-eye"></i>

                </button>


                <!-- Edit -->

                <button
                  type="button"
                  title="Edit"
                  (click)="editResult(result)"
                >

                  <i class="fa-solid fa-pen"></i>

                </button>


                <!-- Delete -->

                <button
                  type="button"
                  title="Delete"
                  (click)="deleteResult(result)"
                >

                  <i class="fa-regular fa-trash-can"></i>

                </button>

              </div>

            </td>

          </tr>


          <!-- =================================================
               Empty State
          ================================================== -->

          <tr
            *ngIf="filteredResults.length === 0"
          >

            <td
              colspan="7"
              class="empty-state"
            >

              <div class="empty-state__icon">

                <i class="fa-solid fa-chart-column"></i>

              </div>

              <strong>
                No results found
              </strong>

              <span>
                Try changing your search or filters.
              </span>

            </td>

          </tr>

        </tbody>

      </table>

    </div>

  </div>

</section>


<!-- =========================================================
     Add Result Modal
========================================================= -->

<div
  class="modal-overlay"
  *ngIf="showAddModal"
>

  <div class="modal-card">

    <h3>
      New Result
    </h3>


    <!-- Student -->

    <div class="form-group">

      <label>
        Student
      </label>

      <input
        type="text"
        [(ngModel)]="newResult.student"
        placeholder="Enter student"
      />

    </div>


    <!-- Exam -->

    <div class="form-group">

      <label>
        Exam
      </label>

      <input
        type="text"
        [(ngModel)]="newResult.exam"
        placeholder="Enter exam"
      />

    </div>


    <!-- Marks -->

    <div class="form-row">

      <div class="form-group">

        <label>
          Marks
        </label>

        <input
          type="number"
          [(ngModel)]="newResult.marks"
          placeholder="Enter marks"
        />

      </div>


      <!-- Total Marks -->

      <div class="form-group">

        <label>
          Total Marks
        </label>

        <input
          type="number"
          [(ngModel)]="newResult.totalMarks"
          placeholder="Enter total marks"
        />

      </div>

    </div>


    <!-- Modal Actions -->

    <div class="modal-actions">

      <button
        type="button"
        class="btn btn--ghost-dark"
        (click)="closeAddResult()"
      >
        Cancel
      </button>

      <button
        type="button"
        class="btn btn--primary modal-save-btn"
        (click)="saveResult()"
      >
        Save Result
      </button>

    </div>

  </div>

</div>


<!-- =========================================================
     Result Details Modal
========================================================= -->

<div
  class="modal-overlay"
  *ngIf="showViewModal && selectedResult"
>

  <div class="modal-card">

    <h3>
      Result Details
    </h3>


    <div class="result-details">

      <div>

        <strong>
          Student:
        </strong>

        {{ getStudentName(selectedResult) }}

      </div>


      <div>

        <strong>
          Student Code:
        </strong>

        {{ getStudentCode(selectedResult) }}

      </div>


      <div>

        <strong>
          Exam:
        </strong>

        {{ getExamTitle(selectedResult) }}

      </div>


      <div>

        <strong>
          Marks:
        </strong>

        {{ getMarks(selectedResult) }}
        /
        {{ getTotalMarks(selectedResult) }}

      </div>


      <div>

        <strong>
          Percentage:
        </strong>

        {{ getPercentage(selectedResult) | number:'1.0-1' }}%

      </div>


      <div>

        <strong>
          Status:
        </strong>

        <span
          class="status-badge"
          [class.status-badge--active]="selectedResult.isPassed === true"
          [class.status-badge--inactive]="selectedResult.isPassed === false"
        >

          <span></span>

          {{ selectedResult.isPassed ? 'Passed' : 'Failed' }}

        </span>

      </div>

    </div>


    <!-- Modal Actions -->

    <div class="modal-actions">

      <button
        type="button"
        class="btn btn--primary modal-save-btn"
        (click)="closeViewResult()"
      >
        Close
      </button>

    </div>

  </div>

</div>


<!-- =========================================================
     Edit Result Modal
========================================================= -->

<div
